contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public payable test function with one parameter to vary inputs
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(true);

        // observe owner before
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;

        // attempt withdraw and record whether it reverted
        bool withdrew;
        c.withdraw{value: 0}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        // observe owner after
        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;

        // If withdraw succeeded when called by this contract, then this contract must have been Owner before
        // and remain Owner after the call.
        assert(!withdrew || (ownerBefore == address(this) && ownerAfter == address(this)));
    }

    receive() external payable {}
}

